const task = $json.data;

if (!task?.id) {
  throw new Error(
    'Directus no devolvió task.id'
  );
}

return [
  {
    json: {
      status: 'updated',
      task
    }
  }
];

const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const taskId = clean(input.task_id);

if (!taskId) {
  throw new Error('task_id es obligatorio');
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(taskId)) {
  throw new Error(
    `task_id no es un UUID válido: ${taskId}`
  );
}

const update = {};

if (input.title !== undefined) {
  const title = clean(input.title);

  if (!title) {
    throw new Error(
      'title no puede quedar vacío'
    );
  }

  update.title = title;
}

if (input.description !== undefined) {
  update.description =
    clean(input.description);
}

if (input.priority !== undefined) {
  const priority = clean(input.priority);

  const allowedPriorities = [
    'low',
    'normal',
    'high',
    'urgent'
  ];

  if (!allowedPriorities.includes(priority)) {
    throw new Error(
      `priority inválida: ${priority}`
    );
  }

  update.priority = priority;
}

if (input.due_at !== undefined) {
  const dueAtRaw = clean(input.due_at);

  if (dueAtRaw === null) {
    update.due_at = null;
  } else {
    const dueAt = new Date(dueAtRaw);

    if (Number.isNaN(dueAt.getTime())) {
      throw new Error(
        `due_at no es una fecha válida: ${dueAtRaw}`
      );
    }

    update.due_at = dueAt.toISOString();
  }
}

if (input.contact_id !== undefined) {
  const contactId = clean(input.contact_id);

  if (contactId !== null) {
    if (!uuidPattern.test(contactId)) {
      throw new Error(
        `contact_id no es un UUID válido: ${contactId}`
      );
    }
  }

  update.contact_id = contactId;
}

if (Object.keys(update).length === 0) {
  throw new Error(
    'No hay campos válidos para actualizar'
  );
}

return [
  {
    json: {
      task_id: taskId,
      update
    }
  }
];
